import{_ as t,o,c as r,a as n}from"./app.DLiRGumz.js";const m=JSON.parse('{"title":"Agent OS Principals — Depth Document","description":"","frontmatter":{},"headers":[],"relativePath":"reference/AGENT_OS_PRINCIPALS_DEPTH.md","filePath":"reference/AGENT_OS_PRINCIPALS_DEPTH.md","lastUpdated":1771753292000}'),a={name:"reference/AGENT_OS_PRINCIPALS_DEPTH.md"};function s(d,e,i,c,l,u){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="agent-os-principals-—-depth-document" tabindex="-1">Agent OS Principals — Depth Document <a class="header-anchor" href="#agent-os-principals-—-depth-document" aria-label="Permalink to &quot;Agent OS Principals — Depth Document&quot;">​</a></h1><p><strong>Purpose:</strong> Options for treating agents as first-class OS principals (beyond sub-user and OS user creation). Enterprise and future deployment patterns.</p><p><strong>Date:</strong> 2026-02-16 <strong>Extends:</strong> CROSS_PLATFORM_GAPS_AND_EXTENSIONS_RESEARCH.md §5, AGENT_IDENTITY_SOVEREIGNTY_DEPTH.md</p><hr><h2 id="_1-current-models" tabindex="-1">1. Current Models <a class="header-anchor" href="#_1-current-models" aria-label="Permalink to &quot;1. Current Models&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th>Isolation</th><th>OS Identity</th><th>Use Case</th></tr></thead><tbody><tr><td><strong>Sub-user</strong></td><td>Process tree only</td><td>None</td><td>Dev, trusted</td></tr><tr><td><strong>OS user</strong></td><td>Real user account</td><td>useradd / New-LocalUser</td><td>Production</td></tr><tr><td><strong>Docker</strong></td><td>Container</td><td>Container user</td><td>Sandbox</td></tr></tbody></table><hr><h2 id="_2-deeper-os-integration-options" tabindex="-1">2. Deeper OS Integration Options <a class="header-anchor" href="#_2-deeper-os-integration-options" aria-label="Permalink to &quot;2. Deeper OS Integration Options&quot;">​</a></h2><h3 id="_2-1-linux-systemd-scope" tabindex="-1">2.1 Linux: systemd Scope <a class="header-anchor" href="#_2-1-linux-systemd-scope" aria-label="Permalink to &quot;2.1 Linux: systemd Scope&quot;">​</a></h3><p><strong>Mechanism:</strong> <code>systemd-run --scope -p MemoryMax=512M -p CPUQuota=50% -- thegent run ...</code></p><p><strong>Pros:</strong> Resource containment without cgroups code; uses systemd <strong>Cons:</strong> Requires systemd; root or user scope <strong>Effort:</strong> Low (4-6 tool calls) <strong>Status:</strong> Recommended for Phase 3 when <code>isolation_mode=osuser</code> on Linux</p><h3 id="_2-2-linux-pam-module" tabindex="-1">2.2 Linux: PAM Module <a class="header-anchor" href="#_2-2-linux-pam-module" aria-label="Permalink to &quot;2.2 Linux: PAM Module&quot;">​</a></h3><p><strong>Mechanism:</strong> Custom PAM module for &quot;agent&quot; authentication; agent logs in as service <strong>Pros:</strong> Full OS auth integration; audit trail <strong>Cons:</strong> High complexity; security-sensitive <strong>Effort:</strong> High <strong>Status:</strong> Document only; future enterprise option</p><h3 id="_2-3-windows-service-account" tabindex="-1">2.3 Windows: Service Account <a class="header-anchor" href="#_2-3-windows-service-account" aria-label="Permalink to &quot;2.3 Windows: Service Account&quot;">​</a></h3><p><strong>Mechanism:</strong> Run thegent as Windows Service under dedicated account (e.g. <code>NT SERVICE\\thegent</code>) <strong>Pros:</strong> Survives logout; proper service lifecycle <strong>Cons:</strong> Requires admin; different execution context <strong>Effort:</strong> Medium <strong>Status:</strong> Document only; future enterprise option</p><h3 id="_2-4-windows-job-objects" tabindex="-1">2.4 Windows: Job Objects <a class="header-anchor" href="#_2-4-windows-job-objects" aria-label="Permalink to &quot;2.4 Windows: Job Objects&quot;">​</a></h3><p><strong>Mechanism:</strong> <code>CreateJobObject</code>, <code>AssignProcessToJobObject</code> with memory/CPU limits <strong>Pros:</strong> Resource containment; no admin for user jobs <strong>Cons:</strong> Windows-specific <strong>Effort:</strong> Medium (8-12 tool calls) <strong>Status:</strong> Add to Phase 3 (see CROSS_PLATFORM_GAPS_AND_EXTENSIONS_RESEARCH §4)</p><h3 id="_2-5-macos-launchd-per-agent" tabindex="-1">2.5 macOS: launchd Per-Agent <a class="header-anchor" href="#_2-5-macos-launchd-per-agent" aria-label="Permalink to &quot;2.5 macOS: launchd Per-Agent&quot;">​</a></h3><p><strong>Mechanism:</strong> Create launchd plist per agent; <code>launchctl load</code><strong>Pros:</strong> Native daemon lifecycle; launch-on-demand <strong>Cons:</strong> macOS only; plist management <strong>Effort:</strong> Medium <strong>Status:</strong> Document only; future option</p><hr><h2 id="_3-implementation-priority" tabindex="-1">3. Implementation Priority <a class="header-anchor" href="#_3-implementation-priority" aria-label="Permalink to &quot;3. Implementation Priority&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Priority</th><th>Phase</th></tr></thead><tbody><tr><td>systemd scope (Linux)</td><td>P1</td><td>Phase 3</td></tr><tr><td>Windows Job Objects</td><td>P1</td><td>Phase 3</td></tr><tr><td>PAM module</td><td>P3</td><td>Future</td></tr><tr><td>Windows Service</td><td>P3</td><td>Future</td></tr><tr><td>launchd per-agent</td><td>P3</td><td>Future</td></tr></tbody></table><hr><h2 id="_4-references" tabindex="-1">4. References <a class="header-anchor" href="#_4-references" aria-label="Permalink to &quot;4. References&quot;">​</a></h2><ul><li><a href="./../research/CROSS_PLATFORM_GAPS_AND_EXTENSIONS_RESEARCH.html">CROSS_PLATFORM_GAPS_AND_EXTENSIONS_RESEARCH.md</a></li><li><a href="./AGENT_IDENTITY_SOVEREIGNTY_DEPTH.html">AGENT_IDENTITY_SOVEREIGNTY_DEPTH.md</a></li><li><a href="./../research/CROSS_PLATFORM_MULTI_TENANT_DESKTOP_AUTOMATION_RESEARCH.html">CROSS_PLATFORM_MULTI_TENANT_DESKTOP_AUTOMATION_RESEARCH.md</a></li><li><a href="./../research/GIT_INDEX_LOCK_OS_LEVEL_AND_AGENT_SYSTEM_USER_PLAN.html">GIT_INDEX_LOCK_OS_LEVEL_AND_AGENT_SYSTEM_USER_PLAN.md</a> — Git wrapper in agent PATH, hooks layout for system user</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p><strong>Extended on:</strong> 2026-02-17 <strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>',34)])])}const _=t(a,[["render",s]]);export{m as __pageData,_ as default};
